type Particle struct{ X, Y, Vx, Vy float32 }

pool := make([]Particle, 0, maxParticles)
pool = append(pool, Particle{X: 1})
for i := range pool {              // values in one backing array, index handles
    pool[i].X += pool[i].Vx * dt
    pool[i].Y += pool[i].Vy * dt
}
